const crypto = require('crypto');
const HMAC_SECRET = 'CHANGE_THIS_TO_YOUR_SECRET_KEY_MIN_32_CHARS';

const q = $input.first().json.query || {};
const bookingId = q.bookingId || '';
const token     = q.token     || '';
const action    = q.action    || '';

// Verify HMAC
const expected = crypto.createHmac('sha256', HMAC_SECRET).update(bookingId).digest('hex');
if (!bookingId || token !== expected) {
  return [{ json: { valid: false, action, bookingId, error: 'Érvénytelen vagy lejárt link.' } }];
}

// Load booking from static data
const sd = $getWorkflowStaticData('global');
const booking = (sd.bookings || {})[bookingId];
if (!booking) {
  return [{ json: { valid: false, action, bookingId, error: 'Foglalás nem található.' } }];
}

return [{ json: { valid: true, action, bookingId, token, booking } }];

